begin;

with input_items as (
  select *
  from jsonb_to_recordset($seed_json$[]$seed_json$::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    aliases text[],
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.aliases, '{}'::text[]) as aliases,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, aliases, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, aliases, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  aliases = excluded.aliases,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset($seed_json$[{"id": "7f8cbe06-9164-549f-9272-145a63fa6d7d", "feature_slug": "core-writing", "title": "1. Lead With The Core Concept", "content": "Use pyramid structure: start with the controlling idea, then unfold the supporting detail below it.\n\nThe top idea changes by format:\n\n| Format | Core concept |\n|---|---|\n| Proposal | What the platform does and how the reader's operation would work on it |\n| Sales deck | The buyer problem, better approach, Rocket solution, or specific decision point |\n| Feature explanation | The feature's purpose, contract, behavior, and limits |\n| Technical explanation | The module responsibility, inputs, outputs, invariants, and failure modes |\n\nBad:\n\n> The platform includes rewards, tiers, campaigns, customer profiles, dashboards, and AI.\n\nBetter:\n\n> Rocket turns purchase activity into a customer profile, then uses that profile to run loyalty, rewards, segmentation, and automated next actions.\n\nThe better version gives the reader the frame first. The list can come later as proof.\n\nThis rule is recursive. Every section, subsection, paragraph, and bullet group should open with its answer or claim before evidence. A reader who skims only the opening lines should still know what each part is saying.\n\nBad — conclusion buried at the end:\n\n> Many CRMs require separate tools for points, campaigns, and analytics. Operators end up reconciling data across systems. Customer profiles fragment across channels. Reporting takes days instead of minutes. Rocket consolidates these into a single platform so operators run loyalty, marketing, and analytics from one customer profile.\n\nBetter — answer first:\n\n> Rocket runs loyalty, marketing, and analytics from a single customer profile. This removes the typical CRM problem: separate tools for points, campaigns, and analytics, fragmented profiles across channels, and reporting that takes days instead of minutes.\n\nThe \"better\" version lets a busy reader stop after the first sentence and still leave with the main point. The detail is there for readers who want it.\n\nQuick test for any section: read only the first sentence of every paragraph. If the reader still understands the argument, the openers are doing their job.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/CORE_WRITING_PRINCIPLES.md#1-lead-with-the-core-concept", "metadata": {"genre": "foundation", "source_file": "CORE_WRITING_PRINCIPLES.md", "section_anchor": "1-lead-with-the-core-concept", "feature_slug": "core-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "50193a6af7a4e2613a43754ce1df1d022a3e2376e3b7a301c6a9604a059174b6", "truncated": false}, "is_active": true}, {"id": "a113a264-2d29-57dd-b104-bcda259518e8", "feature_slug": "core-writing", "title": "10. Avoid Fake Balance", "content": "Good structure does not require equal length.\n\nIf one topic is complex and another is simple, give the complex topic more space. Do not pad simple sections to make the outline look symmetrical.\n\nFake balance makes writing feel machine-generated because real systems have uneven complexity.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/CORE_WRITING_PRINCIPLES.md#10-avoid-fake-balance", "metadata": {"genre": "foundation", "source_file": "CORE_WRITING_PRINCIPLES.md", "section_anchor": "10-avoid-fake-balance", "feature_slug": "core-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "7304b5dc9400e4e45107386e4ae7f57796e3e8c38df0bd8098a208fa77311ed3", "truncated": false}, "is_active": true}, {"id": "74430165-6f5e-5199-b752-e4d138dfe0ac", "feature_slug": "core-writing", "title": "11. Specificity Creates Credibility", "content": "Replace vague claims with observable behavior, concrete scope, examples, numbers, or explicit limits.\n\n| Vague | Specific |\n|---|---|\n| Supports multiple channels | Supports POS, online store, marketplace, receipt upload, and QR scan point collection |\n| Real-time processing | Points calculate and return to the POS before the receipt prints |\n| Flexible campaign management | Campaigns combine actions, conditions, and outcomes without code |\n| Comprehensive reporting | Reports show points issued, rewards redeemed, transaction history, and campaign performance |\n| Secure transaction processing | Staff-initiated transactions require OTP verification and duplicate checks |\n\nDo not call something comprehensive if the scope can be listed. List the scope.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/CORE_WRITING_PRINCIPLES.md#11-specificity-creates-credibility", "metadata": {"genre": "foundation", "source_file": "CORE_WRITING_PRINCIPLES.md", "section_anchor": "11-specificity-creates-credibility", "feature_slug": "core-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "ee990d254ac47da4ffd80a0e33c4388dc2d4c529563c2ce95dfb41fc841dac54", "truncated": false}, "is_active": true}, {"id": "6c46f213-de77-5347-bf75-a22a3ec08c87", "feature_slug": "core-writing", "title": "12. State Limits When They Were Raised", "content": "A limitation is only worth writing when one of these two conditions is true:\n\n1. **The customer explicitly raised the constraint** — in their TOR, Q&A, brief, or email. The constraint is real and the reader expects it to be addressed.\n2. **The constraint is operationally critical** to delivering the feature — e.g. \"POS integration depends on the merchant's POS exposing a REST event webhook.\" Omitting it would mislead the customer about what's needed to go live.\n\nIn all other cases, omit. A list of limitations the customer never asked about reads as a liability register, not as consulting. It makes the proposal feel AI-generated and erodes confidence in the claims that matter.\n\n**Never write a limitation to fill a coverage slot.** The old rule \"state limits honestly\" led to every section ending with a Limitations block. Strict polarity replaces it: no limitation unless the customer raised it or it's operationally critical.\n\n**Unsupported claims are omitted, not demoted.** If you cannot support a capability claim with evidence, remove it or rephrase as a scope statement (\"This proposal does not cover …\"). Do not convert it to a limitation — that is still an assertion about the product, just a negative one.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/CORE_WRITING_PRINCIPLES.md#12-state-limits-when-they-were-raised", "metadata": {"genre": "foundation", "source_file": "CORE_WRITING_PRINCIPLES.md", "section_anchor": "12-state-limits-when-they-were-raised", "feature_slug": "core-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "904b1bc05ddacfd6f231341bc33659e942b711e8c09c99125dcebb77155b06ac", "truncated": false}, "is_active": true}, {"id": "60696987-6eda-54ab-a19a-a90ff82415f7", "feature_slug": "core-writing", "title": "2. Preserve Vertical Logic", "content": "Every child point must directly explain, prove, decompose, or qualify its parent.\n\nIf a detail does not answer the parent's implied question, it belongs elsewhere or should be cut.\n\nExample:\n\n```\nParent: Omnichannel point collection\n    Child: POS purchase earn\n    Child: Online store earn\n    Child: Marketplace claim flow\n    Child: Receipt upload flow\n```\n\nEach child is a point-collection channel. The hierarchy is clean.\n\nMixed:\n\n```\nParent: Omnichannel point collection\n    Child: POS purchase earn\n    Child: Marketing dashboard\n    Child: AI recommendation\n    Child: Customer retention\n```\n\nThe children no longer elaborate the parent. They mix channel, interface, capability, and outcome.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/CORE_WRITING_PRINCIPLES.md#2-preserve-vertical-logic", "metadata": {"genre": "foundation", "source_file": "CORE_WRITING_PRINCIPLES.md", "section_anchor": "2-preserve-vertical-logic", "feature_slug": "core-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "7f46094a941bd1488c987fc41a14c40c9d37428e1b88c4f5cc2ec393d629c7c5", "truncated": false}, "is_active": true}, {"id": "cfa5c02f-6da4-5a7e-8747-9a871894b261", "feature_slug": "core-writing", "title": "3. Preserve Horizontal Logic", "content": "Peer items must be grouped by one dimension at a time.\n\nValid grouping dimensions include:\n\n- By channel: POS, online store, marketplace, receipt upload, QR scan.\n- By lifecycle phase: setup, earn, burn, reporting.\n- By capability: points, tiers, rewards, missions, referrals.\n- By audience: customer, marketer, operator, finance, IT.\n- By system layer: channel, loyalty engine, profile, workflow, analytics.\n\nDo not mix dimensions in one flat list.\n\nMixed dimensions:\n\n```\n1. Fuel stations (touchpoint)\n2. Security (cross-cutting concern)\n3. Merchant On-us (touchpoint)\n4. Mobile app (channel)\n```\n\nGrouped by touchpoint:\n\n```\n1. Fuel stations\n2. Merchant On-us\n3. Merchant NFR\n4. Online store\n5. Rewards\n```\n\nSecurity can be handled inside each touchpoint, then summarized in a separate cross-cutting table.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/CORE_WRITING_PRINCIPLES.md#3-preserve-horizontal-logic", "metadata": {"genre": "foundation", "source_file": "CORE_WRITING_PRINCIPLES.md", "section_anchor": "3-preserve-horizontal-logic", "feature_slug": "core-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "7b78ddece814b810a63d0c51cf8fe9fa1c0377aaae56202017f4dd9b1971d773", "truncated": false}, "is_active": true}, {"id": "937117b8-e4c8-519c-bf35-5b99d5e0c6e3", "feature_slug": "core-writing", "title": "4. Use MECE As A Structure Test", "content": "MECE means mutually exclusive and collectively exhaustive.\n\n- Mutually exclusive: each idea belongs in one primary place. The reader should not feel the same point is being fully explained twice.\n- Collectively exhaustive: the set covers the full scope promised by the parent. The reader should not finish the section asking about an obvious missing case.\n\nMECE is a test, not a visual style. It applies to outlines, slide sections, feature lists, comparison tables, workflows, and checklists.\n\nGood Rocket grouping:\n\n> Convert -> Engage -> Activate\n\nEach stage has a clear role:\n\n- Convert: registration, point collection, unified profile, first-party data capture.\n- Engage: tiers, rewards, missions, referrals, gamified campaigns.\n- Activate: segmentation, churn prediction, personalized offers, automated campaigns.\n\nFailure modes:\n\nOverlapping (not mutually exclusive):\n\n> Loyalty program / Points / Rewards / Tier benefits\n\n\"Loyalty program\" contains the other three. The reader cannot tell whether to expect distinct topics or nested explanations of the same thing. Fix by either dropping the parent (`Points / Rewards / Tiers`) or making the parent a heading and the others its children.\n\nSubtler overlap:\n\n> Customer profile / First-party data / Purchase history / Channel preferences\n\n\"Customer profile\" is the container; the rest are fields inside it. Same problem as above, just less visible.\n\nMissing case (not collectively exhaustive):\n\n> Earn channels: POS, online store\n\nIf the platform also supports marketplace, receipt upload, and QR scan, this list reads as a complete capability claim and undersells the product. The reader either takes it at face value or notices the gap and loses trust. Either list the full set, or scope the heading honestly: \"Earn channels in scope for phase 1: POS, online store.\"\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/CORE_WRITING_PRINCIPLES.md#4-use-mece-as-a-structure-test", "metadata": {"genre": "foundation", "source_file": "CORE_WRITING_PRINCIPLES.md", "section_anchor": "4-use-mece-as-a-structure-test", "feature_slug": "core-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "5c4febd64a254ea3a4eb1f698dd933406b8f7a90cf36847dadd4cd1cacb1eb46", "truncated": false}, "is_active": true}, {"id": "8a68a4c8-5650-5646-92be-7256fe264607", "feature_slug": "core-writing", "title": "5. Cross-Reference Instead Of Duplicating", "content": "MECE does not mean topics cannot depend on each other.\n\nIf one section depends on another, name the dependency and point the reader to the full explanation. Do not repeat the full walkthrough in two places.\n\nGood:\n\n> The earn and burn flows in this section depend on the Merchant Portal for partner registration, reward management, and transaction review. The Merchant Portal is covered in the next section.\n\nThis orients the reader without breaking structure.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/CORE_WRITING_PRINCIPLES.md#5-cross-reference-instead-of-duplicating", "metadata": {"genre": "foundation", "source_file": "CORE_WRITING_PRINCIPLES.md", "section_anchor": "5-cross-reference-instead-of-duplicating", "feature_slug": "core-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "b869e4550fb7e7cc8950d2ec159153ff4383aec2fd41582c75a2a78402c18e8b", "truncated": false}, "is_active": true}, {"id": "2e4e033b-8d83-5f41-a9c7-0aa17fa2da20", "feature_slug": "core-writing", "title": "6. Keep Peer Items At The Same Abstraction Level", "content": "Flat lists should not mix category, feature, channel, outcome, UI detail, and implementation detail.\n\nMixed:\n\n> Loyalty CRM / Points / AI / LINE / Increase retention / Dashboard\n\nThis mixes category, feature, technology, channel, outcome, and interface.\n\nSame level by capability:\n\n> Points / Tiers / Rewards / Missions / Referrals\n\nSame level by outcome:\n\n> Convert customers / Engage members / Activate data\n\nSame level by channel:\n\n> POS / Online store / Marketplace / Receipt upload / QR scan\n\nQuick test: can the group be labeled with one noun phrase? If the label needs \"and\" or \"miscellaneous,\" the list probably mixes abstraction levels.\n\nSide-by-side rewrite. Take the mixed example:\n\n> Loyalty CRM / Points / AI / LINE / Increase retention / Dashboard\n\nThe same items, re-sorted into valid groupings:\n\n| Dimension | Items |\n|---|---|\n| Capability | Points, tiers, rewards, missions, referrals |\n| Channel | LINE, SMS, email, push, in-app |\n| Technology | AI segmentation, AI churn prediction, AI offer ranking |\n| Interface | Operator dashboard, customer app, merchant portal |\n| Outcome | Increase retention, lift basket size, recover churned customers |\n\nEach row passes the noun-phrase test. Mixing rows back into one bullet list breaks it again.\n\nSubtler mix:\n\n> POS / Online store / Mobile app / Marketplace / Receipt upload\n\nThis looks like channels, but \"Mobile app\" is an interface that spans several of them — a customer can earn points in the app from an online order, a marketplace claim, or a receipt upload. The mix is invisible until a reader asks \"where does the mobile app fit?\" Fix by separating the dimensions:\n\n> Channels: POS, online store, marketplace, receipt upload, QR scan\n>\n> Interfaces: customer mobile app, customer web, operator dashboard, merchant portal\n\nThe drift that's easiest to miss is usually one item that looks like a peer but actually cuts across the others.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/CORE_WRITING_PRINCIPLES.md#6-keep-peer-items-at-the-same-abstraction-level", "metadata": {"genre": "foundation", "source_file": "CORE_WRITING_PRINCIPLES.md", "section_anchor": "6-keep-peer-items-at-the-same-abstraction-level", "feature_slug": "core-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "eebadd98438c4461cfba03b77a93adfd84c792916563cfdfbec91bd9cb05ed3a", "truncated": false}, "is_active": true}, {"id": "875574f5-a9d7-5ce6-879b-9905c118ad62", "feature_slug": "core-writing", "title": "7. Use Parallel Structure For Peer Points", "content": "Peer points should carry similar conceptual weight and grammar.\n\nWeak:\n\n```\n1. Points can be earned at POS\n2. Rewards\n3. Customers receive LINE notifications\n4. Dashboard analytics\n```\n\nParallel by customer journey:\n\n```\n1. Customer earns points at POS\n2. Customer redeems rewards in the app\n3. Customer receives LINE notifications\n4. Customer tracks tier progress\n```\n\nParallel by operator capability:\n\n```\n1. Configure earn rules\n2. Configure reward inventory\n3. Configure LINE messages\n4. Review campaign performance\n```\n\nThe rule is not that every line must sound identical. The rule is that peers should be comparable.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/CORE_WRITING_PRINCIPLES.md#7-use-parallel-structure-for-peer-points", "metadata": {"genre": "foundation", "source_file": "CORE_WRITING_PRINCIPLES.md", "section_anchor": "7-use-parallel-structure-for-peer-points", "feature_slug": "core-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "26bdf334106f9a878881dddc68b4efb8633ee72f39db7fdda19b7a17d738658f", "truncated": false}, "is_active": true}, {"id": "e655706c-e69c-579c-8aa5-192dbff06621", "feature_slug": "core-writing", "title": "8. Mix Levels Only When The Relationship Is Explicit", "content": "Do not mix abstraction levels in a flat list.\n\nYou may mix levels in a hierarchy, journey, matrix, architecture diagram, or system flow when the layout makes the relationship clear.\n\nAllowed:\n\n- Hierarchy: `Convert -> Engage -> Activate`, with example features under each stage.\n- Journey: `Customer buys on Shopee -> claims points -> joins tier -> receives AI offer`.\n- System diagram: `Purchase channel -> loyalty engine -> customer profile -> AMP workflow -> LINE message`.\n- Matrix: online/offline rows against brand-owned/third-party columns.\n\nThe structure must show why the levels are different and how they relate.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/CORE_WRITING_PRINCIPLES.md#8-mix-levels-only-when-the-relationship-is-explicit", "metadata": {"genre": "foundation", "source_file": "CORE_WRITING_PRINCIPLES.md", "section_anchor": "8-mix-levels-only-when-the-relationship-is-explicit", "feature_slug": "core-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "7c740c9388227ca66be47575c3bcb586b182fb3f45d6270032049f7d428a5253", "truncated": false}, "is_active": true}, {"id": "a1c45d97-6217-508b-aae1-20fa535d9a48", "feature_slug": "core-writing", "title": "9. Use Layered Depth", "content": "Write so different readers can stop at the right depth.\n\nCommon depth pattern:\n\n```\nLevel 1: Overview or core concept\nLevel 2: Main parts, stages, or options\nLevel 3: Flow, examples, or evidence\nLevel 4: Edge cases, limits, configuration, or implementation detail\nLevel 5: Summary matrix or checklist\n```\n\nExecutives should be able to read the overview and summary. Technical or operational readers should be able to find the deeper detail without guessing where it lives.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/CORE_WRITING_PRINCIPLES.md#9-use-layered-depth", "metadata": {"genre": "foundation", "source_file": "CORE_WRITING_PRINCIPLES.md", "section_anchor": "9-use-layered-depth", "feature_slug": "core-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "bb030161895660280a8e6338d18fb153deeba207d154b2ef609de7a16ba02964", "truncated": false}, "is_active": true}, {"id": "55b7c639-2ba3-5266-af38-2aefa2daf87b", "feature_slug": "core-writing", "title": "Core Checklist", "content": "### Core Concept\n\n- [ ] Does the section lead with the controlling idea before detail?\n- [ ] Does every subsection and paragraph open with its answer or claim, not bury it at the end?\n- [ ] Can the reader understand the point from the headings and paragraph openers alone?\n\n### Vertical Logic\n\n- [ ] Does every child point directly explain, prove, decompose, or qualify its parent?\n- [ ] Are misplaced details moved or cut?\n\n### Horizontal Logic\n\n- [ ] Are peer items grouped by one dimension at a time?\n- [ ] Can each group be labeled with one clear noun phrase?\n\n### MECE\n\n- [ ] Is each major idea explained in one primary place?\n- [ ] Are obvious gaps covered?\n- [ ] Are dependencies handled with cross-references instead of duplicated walkthroughs?\n\n### Abstraction Level\n\n- [ ] Do flat lists keep peer items at the same abstraction level?\n- [ ] Are mixed levels only used in hierarchies, journeys, matrices, or diagrams where the relationship is explicit?\n- [ ] Do peer bullets use parallel grammar and conceptual weight?\n\n### Depth And Credibility\n\n- [ ] Does the structure support both scanning and deeper reading?\n- [ ] Does real complexity determine section length?\n- [ ] Are vague claims replaced with concrete behavior, scope, examples, numbers, or limits?", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/CORE_WRITING_PRINCIPLES.md#core-checklist", "metadata": {"genre": "foundation", "source_file": "CORE_WRITING_PRINCIPLES.md", "section_anchor": "core-checklist", "feature_slug": "core-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "53110646ed97b75b6a7aa9795e4126f1ac32b0af63c3c4a1fb9c2879a778f6c5", "truncated": false}, "is_active": true}, {"id": "54fc26e1-dbe4-587f-8a67-5deecc4f6ac5", "feature_slug": "core-writing", "title": "Core Writing Principles — Overview", "content": "**When to use:** Every structured writing task — proposals, slides, web copy, feature guides, emails. Pyramid logic, MECE, vertical/horizontal logic, specificity, limits.\n            **Source:** `CORE_WRITING_PRINCIPLES.md`\n            **Genre:** `foundation`\n\n**Universal:** Apply alongside every other playbook.\n\n            These principles govern structured writing across Rocket materials: proposals, sales decks, feature explanations, internal docs, and agent responses.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/CORE_WRITING_PRINCIPLES.md", "metadata": {"genre": "foundation", "source_file": "CORE_WRITING_PRINCIPLES.md", "section_anchor": "overview", "feature_slug": "core-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "f634d3d2faca5e16844c9628e5cc1d17944cca75db9de8268d7d7ce7d31f6614", "truncated": false}, "is_active": true}, {"id": "0e93f627-733c-590a-a0cd-f82881723e0d", "feature_slug": "core-writing", "title": "Purpose", "content": "These principles govern structured writing across Rocket materials: proposals, sales decks, feature explanations, internal docs, and agent responses.\n\nUse this document when the task requires clear reasoning, hierarchy, grouping, or explanation. Use the format-specific documents only after this foundation:\n\n- `PROPOSAL_WRITING_PRINCIPLES.md` for B2B SaaS proposals, RFPs, and long-form platform walkthroughs.\n- `SALES_PRESENTATION_SLIDE_PRINCIPLES.md` for Rocket CRM sales and marketing slides.\n\nGood structured writing lets the reader answer four questions quickly:\n\n1. What is the main point?\n2. How are the supporting ideas organized?\n3. What belongs together, and what does not?\n4. How much detail do I need to read before I understand the answer?\n\n---", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/CORE_WRITING_PRINCIPLES.md#purpose", "metadata": {"genre": "foundation", "source_file": "CORE_WRITING_PRINCIPLES.md", "section_anchor": "purpose", "feature_slug": "core-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "6435fba600929d059bfdc12c23badec1310a8309436551f02a65928fc111c96d", "truncated": false}, "is_active": true}, {"id": "417a664f-5a93-5d28-adcf-e46e81d63d79", "feature_slug": "feature-guide-writing", "title": "Audiences (all four, in every section)", "content": "1. **AI Testing Agents** — config→behavior mappings, assertions, edge cases\n2. **Marketing / Design** — value propositions, use-case stories, plain-language descriptions\n3. **Customer Success** — onboarding scripts, FAQ answers, troubleshooting\n4. **Product** — capability inventory, feature connections, quick reference\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["customer_success", "general", "product"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/FEATURE_GUIDE_WRITING_PRINCIPLES.md#audiences-all-four-in-every-section", "metadata": {"genre": "feature_guide", "source_file": "FEATURE_GUIDE_WRITING_PRINCIPLES.md", "section_anchor": "audiences-all-four-in-every-section", "feature_slug": "feature-guide-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "f4d29c8cc6b6aa11f31574202c0a191a816e71a289c2a399d7b9c92b00fa63f6", "truncated": false}, "is_active": true}, {"id": "507598ce-47de-5aba-8e4f-31be15c776e3", "feature_slug": "feature-guide-writing", "title": "Context Efficiency Rules", "content": "There will be ~20 feature guides. Multiple may load simultaneously. Every wasted line is multiplied.\n\n### No Redundancy Within a Doc\n\n- Define a term ONCE in Key Concepts. Other sections use it without re-explaining.\n- State a business rule ONCE in Business Rules. Journeys reference the rule by its effect.\n- Configuration is described ONCE in Configuration Reference. Admin Journey says \"fill in the eligibility conditions\" not \"set the allowed tiers, personas, and birth month filters.\"\n\n### No Redundancy Across Docs\n\nEach guide owns its domain. Other domains get one-line references in Related Features.\n\n- Do NOT explain how points work in the Rewards guide — that's Currency's job.\n- Do NOT explain tier logic in the Rewards guide — just reference eligibility can be tier-gated.\n\n### No Boilerplate\n\n- No \"In this section we will discuss...\" introductions\n- No \"As mentioned above...\" cross-references within the same doc\n- No generic loyalty program explanations — the Feature Index provides platform context\n- Jump straight into content\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["customer_success", "general", "product"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/FEATURE_GUIDE_WRITING_PRINCIPLES.md#context-efficiency-rules", "metadata": {"genre": "feature_guide", "source_file": "FEATURE_GUIDE_WRITING_PRINCIPLES.md", "section_anchor": "context-efficiency-rules", "feature_slug": "feature-guide-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "4aca81905f5c80665a02aef10a570b692e513773d46474d1ddf701511d7ec20d", "truncated": false}, "is_active": true}, {"id": "0846cfbe-1944-56d8-92cf-0240e5820b86", "feature_slug": "feature-guide-writing", "title": "Feature Guide Writing — Overview", "content": "**When to use:** CRM feature guides in requirements/feature-docs. 8-section template, multi-audience, route maps, status models.\n**Source:** `FEATURE_GUIDE_WRITING_PRINCIPLES.md`\n**Genre:** `feature_guide`\n\nStructured product docs for testers, marketing, CS, and product", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["customer_success", "general", "product"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/FEATURE_GUIDE_WRITING_PRINCIPLES.md", "metadata": {"genre": "feature_guide", "source_file": "FEATURE_GUIDE_WRITING_PRINCIPLES.md", "section_anchor": "overview", "feature_slug": "feature-guide-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "68c7434078b42f0fd4647e941dd05f60ff674d06f7a93ba8d46d83c0e530b871", "truncated": false}, "is_active": true}, {"id": "5ef28170-387d-54c8-94e3-840dca8ec664", "feature_slug": "feature-guide-writing", "title": "Gathering Information — Three Sources", "content": "Before writing, gather from all three:\n\n1. **Local requirement docs** (`requirements/*.md`) — business rules, concepts, schemas, API specs\n2. **GitHub MCP → `Rocket-CRM/loyalty-admin`** — admin journey (routes, form fields, buttons, validation)\n3. **GitHub MCP → `Rocket-CRM/loyalty-user`** — member journey (screens, drawers, navigation, states)\n\nRead `ProjectDocs/FE_docs/` in both repos for page-level documentation. Read actual component files for details not covered in docs.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["customer_success", "general", "product"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/FEATURE_GUIDE_WRITING_PRINCIPLES.md#gathering-information-three-sources", "metadata": {"genre": "feature_guide", "source_file": "FEATURE_GUIDE_WRITING_PRINCIPLES.md", "section_anchor": "gathering-information-three-sources", "feature_slug": "feature-guide-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "3848ac3464beb1054ed5c0fbb5dd243084ada868b73b05b8f15b7f70c09cf3c8", "truncated": false}, "is_active": true}, {"id": "463d5482-d2a5-5599-83dc-d6b3b72a26f3", "feature_slug": "feature-guide-writing", "title": "Line Budget", "content": "**Target: 250–400 lines.** If you exceed 400 lines, you are being redundant. Cut repeated information, not coverage.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["customer_success", "general", "product"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/FEATURE_GUIDE_WRITING_PRINCIPLES.md#line-budget", "metadata": {"genre": "feature_guide", "source_file": "FEATURE_GUIDE_WRITING_PRINCIPLES.md", "section_anchor": "line-budget", "feature_slug": "feature-guide-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "45bd6e5a4774e018ca140e907ee87f1a2c62f211455a7dda9771e08f2ee4f130", "truncated": false}, "is_active": true}, {"id": "4482f805-441c-58f2-91d1-b8188d1bdc7b", "feature_slug": "feature-guide-writing", "title": "Purpose", "content": "These principles govern **Feature Guides** in `requirements/feature-docs/`. They sit between deep technical requirement specs (`requirements/*.md`) and the codebase. They are not for engineers building the feature — those use the requirement docs.\n\nFor universal structure, clarity, and voice rules, read `CORE_WRITING_PRINCIPLES.md` first. This document adds format-specific rules only.\n\n---", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["customer_success", "general", "product"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/FEATURE_GUIDE_WRITING_PRINCIPLES.md#purpose", "metadata": {"genre": "feature_guide", "source_file": "FEATURE_GUIDE_WRITING_PRINCIPLES.md", "section_anchor": "purpose", "feature_slug": "feature-guide-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "4f1ab8dfa61f5138a3b331289efead4375516ede24e51d7f6e20137761941aeb", "truncated": false}, "is_active": true}, {"id": "1b1416d8-784c-505a-aaa7-15fde87bc0ba", "feature_slug": "feature-guide-writing", "title": "Quality Checklist", "content": "Before finishing a feature guide:\n\n- [ ] All 8 sections present with correct structure\n- [ ] Key Concepts defines every term used in later sections\n- [ ] Config Reference matches the actual admin UI form (verified from loyalty-admin repo)\n- [ ] Route map tables present in Sections 4 and 5 — no hardcoded paths in steps\n- [ ] Status model fully enumerated (all values, transitions, independence)\n- [ ] No term re-explained after Key Concepts\n- [ ] No business rule restated after Business Rules\n- [ ] No cross-domain knowledge duplicated (one-line + link only)\n- [ ] 6a/6b/6c don't overlap with each other or with earlier sections\n- [ ] Under 400 lines\n- [ ] No AI filler words (comprehensive, robust, seamless, leverage, cutting-edge)\n- [ ] Feature Index updated\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["customer_success", "general", "product"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/FEATURE_GUIDE_WRITING_PRINCIPLES.md#quality-checklist", "metadata": {"genre": "feature_guide", "source_file": "FEATURE_GUIDE_WRITING_PRINCIPLES.md", "section_anchor": "quality-checklist", "feature_slug": "feature-guide-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "5d65dc1d0298b0c1dc18d4456f42b4ec6d0e28268d83133111c34afad499890b", "truncated": false}, "is_active": true}, {"id": "49867171-c416-5d9f-8d8c-a3b70b276649", "feature_slug": "feature-guide-writing", "title": "Route Map Pattern", "content": "Do NOT hardcode route paths in journey steps — routes change and silently break the doc. Instead:\n\n1. Place a **route map table** at the top of each journey section (Admin Journey, Member Experience)\n2. The table maps: Page Name → Current Route → Data Source / BFF\n3. Steps reference **page names only** (\"From **Reward List**, click...\")\n4. When a route changes, update one row in the table — not every step\n\nAlso note the **repo** at the top of each journey section (`Rocket-CRM/loyalty-admin` or `Rocket-CRM/loyalty-user`).\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["customer_success", "general", "product"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/FEATURE_GUIDE_WRITING_PRINCIPLES.md#route-map-pattern", "metadata": {"genre": "feature_guide", "source_file": "FEATURE_GUIDE_WRITING_PRINCIPLES.md", "section_anchor": "route-map-pattern", "feature_slug": "feature-guide-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "bd17181adfff7b2c0460c281a93c49e9b356ca43a6a0b5de5eca96898688651f", "truncated": false}, "is_active": true}, {"id": "e35a5ffa-7d94-5411-83bb-9b9b34969fd0", "feature_slug": "feature-guide-writing", "title": "Status Models", "content": "When a feature has multiple status tracks (e.g., redeemed vs. used vs. fulfillment), enumerate all values and their relationships explicitly. Don't just say \"status changes from X to Y\" — show:\n\n- All possible values for each status field\n- Which transitions are valid\n- How the statuses are independent or dependent\n- What member-facing UI labels map to which status combinations\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["customer_success", "general", "product"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/FEATURE_GUIDE_WRITING_PRINCIPLES.md#status-models", "metadata": {"genre": "feature_guide", "source_file": "FEATURE_GUIDE_WRITING_PRINCIPLES.md", "section_anchor": "status-models", "feature_slug": "feature-guide-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "9db78b36e9a4698582a916442294dcef95a2ea7b240d6b4107a5f42ebb05e867", "truncated": false}, "is_active": true}, {"id": "ed859080-2e66-5b41-8476-cdbfa208dc4c", "feature_slug": "feature-guide-writing", "title": "Template — 8 Sections", "content": "Every guide follows this exact structure:\n\n| # | Section | Tone | Primary consumers |\n|---|---|---|---|\n| 1 | Overview | Natural prose, 2-3 paragraphs | Marketing, Product, CS |\n| 2 | Key Concepts | Term → definition → example | All (glossary) |\n| 3 | Configuration Reference | Tables grouped by admin UI sections | Testers, CS |\n| 4 | Admin Journey | Numbered steps with route map | Testers, CS |\n| 5 | Member Experience | Numbered steps with route map | Testers, Marketing |\n| 6 | Perspectives (CS / Marketing / Testers) | Audience-specific language | One subsection per audience |\n| 7 | Business Rules | Rule + Example format | Testers, CS, Product |\n| 8 | Related Features | Table: feature → one-sentence connection | All |\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["customer_success", "general", "product"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/FEATURE_GUIDE_WRITING_PRINCIPLES.md#template-8-sections", "metadata": {"genre": "feature_guide", "source_file": "FEATURE_GUIDE_WRITING_PRINCIPLES.md", "section_anchor": "template-8-sections", "feature_slug": "feature-guide-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "2fc6ed1e730c2c27f2b4a805d20ee2633f9c998d1a23c743d80c5af0768f6125", "truncated": false}, "is_active": true}]$seed_json$::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

commit;
